import { useEffect, useRef, useState } from "react";
import { ActivityIndicator, Pressable, StyleSheet, Text } from "react-native";
import type { PressableProps, StyleProp, TextStyle, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface ActionButtonProps extends Omit<PressableProps, "style" | "children" | "onPress"> {
  label: string;
  successLabel?: string;
  pendingLabel?: string;
  /** Runs when pressed. A promise drives the pending and success states. */
  onAction: () => void | Promise<void>;
  /** Milliseconds the success state shows before the button returns to idle. */
  resetAfterMs?: number;
  onActionError?: (error: unknown) => void;
  style?: StyleProp<ViewStyle>;
  /** Extend the inner, named parts of the action button: label or spinner. The React Native counterpart of `classNames`. */
  styles?: {
    label?: StyleProp<TextStyle>;
  };
}

type Phase = "idle" | "pending" | "success";

export function ActionButton({ label, successLabel = "Done", pendingLabel, onAction, resetAfterMs = 1600, onActionError, disabled, style, styles: parts, ...props }: ActionButtonProps) {
  const tokens = useTokens();
  const [phase, setPhase] = useState<Phase>("idle");
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  useEffect(() => () => clearTimeout(timer.current), []);

  async function press() {
    if (phase !== "idle") return;
    setPhase("pending");
    try {
      await onAction();
      setPhase("success");
      timer.current = setTimeout(() => setPhase("idle"), resetAfterMs);
    } catch (error) {
      setPhase("idle");
      onActionError?.(error);
    }
  }

  const color = phase === "success" ? tokens.success : tokens.background;

  return (
    <Pressable
      {...props}
      accessibilityRole="button"
      accessibilityState={{ busy: phase === "pending", disabled: Boolean(disabled) }}
      disabled={disabled}
      onPress={press}
      style={({ pressed }) => [
        local.root,
        { minHeight: metrics.controlHeight.md, borderColor: phase === "success" ? tokens.success : tokens.foreground, backgroundColor: phase === "success" ? tokens.surface : tokens.foreground, opacity: disabled ? 0.52 : pressed ? 0.85 : 1 },
        style,
      ]}
    >
      {phase === "pending" ? <ActivityIndicator size="small" color={color} /> : null}
      <Text style={[{ color, fontSize: metrics.text.sm, fontWeight: "500" }, parts?.label]}>
        {phase === "success" ? `✓ ${successLabel}` : phase === "pending" ? (pendingLabel ?? label) : label}
      </Text>
    </Pressable>
  );
}

const local = StyleSheet.create({
  root: { flexDirection: "row", alignItems: "center", justifyContent: "center", alignSelf: "flex-start", gap: 8, paddingHorizontal: metrics.space[4], borderWidth: 1, borderRadius: metrics.radiusControl },
});

export default ActionButton;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
